def bbox_of_component(grid, seen, r0,c0):
    from collections import deque
    color=grid[r0][c0]
    q=deque([(r0,c0)]); seen.add((r0,c0))
    cells=[]
    while q:
        r,c=q.popleft(); cells.append((r,c))
        for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
