                # reverse chain
                rev=chain[::-1]
                # apply: pixels inside top rect: depth = number of enclosing borders
                # compute depth per pixel: smallest k such that pixel inside k-th inner rect
                ds=[top]
                depths={}
                # for each rect in chain assign depths
                rects=[]
                bounds=top
                for k in range(len(chain)):
