            if grid[i][j] and not seen[i][j]:
                comp=[]; q=deque([(i,j)]); seen[i][j]=True
                while q:
                    y,x=q.popleft(); comp.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and grid[ny][nx] and not seen[ny][nx]:
                            seen[ny][nx]=True; q.append((ny,nx))
                boxes={}
                for y,x in comp:
                    boxes.setdefault(grid[y][x],[y,y,x,x])
                    b=boxes[grid[y][x]]
                    b[0]=min(b[0],y);b[1]=max(b[1],y);b[2]=min(b[2],x);b[3]=max(b[3],x)
